'use strict';
window.TravelTools=(()=>{
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let settings={from:'KRW',to:'auto',amount:10000,rateMode:'reference',manualRate:'',weatherMode:'trip',weatherCity:null,language:'auto',phrase:0};try{Object.assign(settings,JSON.parse(localStorage.getItem('travel-tools-v1')||'{}'))}catch{}
let destination=null,city='',currencyRequest=0,weatherRequest=0,searchRequest=0,weatherResults=[],lastRate=null,gpsLocation=null;
const currencyCountries={KR:'KRW',US:'USD',GB:'GBP',JP:'JPY',CN:'CNY',TW:'TWD',HK:'HKD',TH:'THB',VN:'VND',SG:'SGD',MY:'MYR',ID:'IDR',PH:'PHP',IN:'INR',AU:'AUD',NZ:'NZD',CA:'CAD',CH:'CHF',SE:'SEK',NO:'NOK',DK:'DKK',PL:'PLN',CZ:'CZK',HU:'HUF',TR:'TRY',AE:'AED',SA:'SAR',BR:'BRL',MX:'MXN',ZA:'ZAR',EG:'EGP'};
const euroCountries='FR DE IT ES PT NL BE AT IE GR FI EE LV LT LU MT CY SK SI HR'.split(' ');
const localCurrency=()=>currencyCountries[destination.country]||(euroCountries.includes(destination.country)?'EUR':'USD');
const languageCountries={KR:'ko',JP:'ja',FR:'fr',MC:'fr',DE:'de',AT:'de',ES:'es',MX:'es',AR:'es',CO:'es',PE:'es',CL:'es',IT:'it',PT:'pt',BR:'pt',TH:'th',CN:'zh',TW:'zh',HK:'zh',AE:'ar',SA:'ar',EG:'ar',GB:'en',US:'en',AU:'en',NZ:'en',CA:'en',IE:'en',SG:'en',IN:'hi',VN:'vi'};
const phrases=['Hello','Where are the restrooms?','The bill, please','Thank you very much'];
const languages={
en:{name:'English',voice:'en-US',phrases:['Hello!','Where are the restrooms?','The bill, please.','Thank you very much!']},
ko:{name:'Korean · 한국어',voice:'ko-KR',phrases:['안녕하세요.','화장실은 어디인가요?','계산서 부탁합니다.','정말 감사합니다.']},
fr:{name:'French · Français',voice:'fr-FR',phrases:['Bonjour !','Où sont les toilettes ?','L’addition, s’il vous plaît.','Merci beaucoup !']},
ja:{name:'Japanese · 日本語',voice:'ja-JP',phrases:['こんにちは。','トイレはどこですか？','お会計をお願いします。','どうもありがとうございます。']},
es:{name:'Spanish · Español',voice:'es-ES',phrases:['¡Hola!','¿Dónde están los baños?','La cuenta, por favor.','¡Muchas gracias!']},
de:{name:'German · Deutsch',voice:'de-DE',phrases:['Guten Tag!','Wo sind die Toiletten?','Die Rechnung, bitte.','Vielen Dank!']},
it:{name:'Italian · Italiano',voice:'it-IT',phrases:['Buongiorno!','Dove sono i bagni?','Il conto, per favore.','Grazie mille!']},
pt:{name:'Portuguese · Português',voice:'pt-PT',phrases:['Olá!','Onde fica o banheiro?','A conta, por favor.','Muito obrigado!']},
th:{name:'Thai · ไทย',voice:'th-TH',phrases:['สวัสดี','ห้องน้ำอยู่ที่ไหน','ขอเช็คบิลด้วย','ขอบคุณมาก']},
zh:{name:'Chinese · 中文',voice:'zh-CN',phrases:['你好！','洗手间在哪里？','请结账。','非常感谢！']},
ar:{name:'Arabic · العربية',voice:'ar-SA',phrases:['مرحبًا','أين دورة المياه؟','الحساب من فضلك.','شكرًا جزيلًا.']},
hi:{name:'Hindi · हिन्दी',voice:'hi-IN',phrases:['नमस्ते।','शौचालय कहाँ है?','बिल दीजिए।','बहुत धन्यवाद।']},
vi:{name:'Vietnamese · Tiếng Việt',voice:'vi-VN',phrases:['Xin chào!','Nhà vệ sinh ở đâu?','Cho tôi xin hóa đơn.','Cảm ơn rất nhiều!']}
};
const $=s=>document.querySelector(s),persist=()=>{try{localStorage.setItem('travel-tools-v1',JSON.stringify(settings))}catch{}},targetCurrency=()=>settings.to==='auto'?localCurrency():settings.to,targetLanguage=()=>settings.language==='auto'?(languageCountries[destination.country]||'en'):settings.language;
const codes=typeof Intl.supportedValuesOf==='function'?Intl.supportedValuesOf('currency'):['USD','EUR','KRW','JPY','GBP','CNY','CAD','AUD','CHF','THB','VND','SGD'];const names=new Intl.DisplayNames(['en'],{type:'currency'});
const currencyOptions=value=>codes.map(c=>`<option value="${c}" ${c===value?'selected':''}>${c} · ${escape(new Intl.DisplayNames([window.AppI18n?.locale||'en'],{type:'currency'}).of(c))}</option>`).join('');
function render(context){destination=context.destination;city=context.city;lastRate=null;return `<div class="view-heading"><div><div class="eyebrow">LITTLE TRAVEL HELPERS</div><h1>Small tools. Your way.</h1><p class="muted small-text">Use your destination’s defaults, or make them your own.</p></div></div><section class="panel page-panel app-language-panel" style="margin-bottom:20px"><h3>Language</h3><label class="utility-label">App language<select id="app-language"><option value="en" ${window.AppI18n?.locale!=='ko'?'selected':''}>English</option><option value="ko" ${window.AppI18n?.locale==='ko'?'selected':''}>한국어</option></select></label><p class="small-text muted">Menus, place stories and tour narration all follow this setting. Phrasebook pronunciation stays in the language you are learning.</p><p class="footnote">Your preference is saved on this device.</p></section><div class="tool-grid"><section class="panel page-panel utility-currency"><div class="section-title"><h3>Currency converter</h3><span class="pill">Your choice</span></div><div class="currency-pair"><label>From<select id="currency-from">${currencyOptions(settings.from)}</select></label><button class="btn" data-tool="swap-currencies" aria-label="Swap currencies">⇄</button><label>To<select id="currency-to"><option value="auto" ${settings.to==='auto'?'selected':''}>Trip suggestion · ${localCurrency()}</option>${currencyOptions(settings.to)}</select></label></div><label class="utility-label">Amount<input id="currency-amount" type="number" min="0" max="1000000000000" step="any" value="${Number(settings.amount)||0}"></label><label class="utility-label">Exchange rate<select id="currency-mode"><option value="reference" ${settings.rateMode==='reference'?'selected':''}>Latest published reference rate</option><option value="manual" ${settings.rateMode==='manual'?'selected':''}>Enter my own rate</option></select></label><label class="utility-label ${settings.rateMode==='manual'?'':'hide'}" id="manual-rate-label">1 <span id="manual-from">${settings.from}</span> = <input type="number" id="manual-rate" min="0.000000001" step="any" placeholder="Enter rate" value="${escape(settings.manualRate)}"> <span id="manual-to">${targetCurrency()}</span></label><button class="btn primary" data-tool="convert" style="margin-top:14px">Convert</button><div class="currency-output" id="currency-output" role="status">—</div><p id="currency-note" class="small-text muted">Reference rates exclude bank fees and are not live trading quotes.</p></section><section class="panel page-panel utility-weather"><h3>Weather, wherever you are</h3><div class="weather-choice"><button class="pref ${settings.weatherMode==='trip'?'active':''}" data-tool="weather-trip">My trip · ${escape(city)}</button><button class="pref ${settings.weatherMode==='gps'?'active':''}" data-tool="weather-gps">My location</button><button class="pref ${settings.weatherMode==='custom'?'active':''}" data-tool="weather-custom">Choose a city</button></div><div id="weather-search-area" class="${settings.weatherMode==='custom'?'':'hide'}"><div class="inline-form"><input id="weather-city-search" aria-label="Weather city" placeholder="Search any city"><button class="btn" data-tool="weather-search">Search</button></div><div id="weather-city-results"></div></div><p id="weather-place" class="small-text">${escape(weatherLabel())}</p><button class="btn" data-tool="weather-refresh">Refresh weather</button><div id="weather-output" role="status"><p class="muted">Choose a location and refresh to see the weather.</p></div><p class="footnote">Forecasts: <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a> · City search: GeoNames</p></section><section class="panel page-panel utility-phrases"><h3>Say it like you mean it</h3><label class="utility-label">Language<select id="phrase-language"><option value="auto" ${settings.language==='auto'?'selected':''}>Trip suggestion · ${escape(languages[languageCountries[destination.country]||'en'].name)}</option>${Object.entries(languages).map(([k,l])=>`<option value="${k}" ${settings.language===k?'selected':''}>${escape(l.name)}</option>`).join('')}</select></label><p class="small-text muted">A country may use several languages. Choose the one you need.</p><label class="utility-label">What would you like to say?<select id="travel-phrase">${phrases.map((p,i)=>`<option value="${i}" ${Number(settings.phrase)===i?'selected':''}>${p}</option>`).join('')}</select></label><p id="spoken-phrase" class="spoken-phrase" dir="auto">${escape(languages[targetLanguage()].phrases[Number(settings.phrase)||0])}</p><button class="btn primary" data-tool="pronounce">▷ Listen to pronunciation</button><button class="btn" data-tool="stop-pronunciation">Stop</button><p id="pronunciation-status" class="footnote" role="status">Uses the selected language’s voice on your device.</p><p class="small-text"><a id="open-translator" href="https://translate.google.com/?sl=auto&tl=${targetLanguage()}&text=${encodeURIComponent(languages[targetLanguage()].phrases[Number(settings.phrase)||0])}&op=translate" target="_blank" rel="noopener">Hear this phrase in Google Translate ↗</a></p></section><section class="panel page-panel utility-time"><h3>${escape(city)} right now</h3><div class="big-number" id="paris-time"></div><p id="seoul-time"></p><p class="muted">Local times account for daylight saving.</p></section></div>`}
function weatherLabel(){return settings.weatherMode==='trip'?city:settings.weatherMode==='gps'?'Current location':settings.weatherCity?.name||'Choose a city below'}
function updateCurrency(){currencyRequest++;lastRate=null;$('#currency-output').textContent='—';$('#currency-note').textContent='Choose Convert to calculate this currency pair.';$('#manual-from').textContent=settings.from;$('#manual-to').textContent=targetCurrency();persist()}
async function convert(){const amount=Number(settings.amount),from=settings.from,to=targetCurrency(),request=++currencyRequest,output=$('#currency-output'),note=$('#currency-note');if(!Number.isFinite(amount)||amount<0||amount>1e12){output.textContent='Enter a valid amount.';return}output.textContent='Calculating…';try{let rate,date;if(from===to){rate=1;date=null}else if(settings.rateMode==='manual'){rate=Number(settings.manualRate);if(!Number.isFinite(rate)||rate<=0)throw Error('Enter a positive exchange rate.')}else{const r=await fetch(`https://api.frankfurter.dev/v2/rate/${from.toLowerCase()}/${to.toLowerCase()}`,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('No reference rate is available. Try another pair or enter your own rate.');const d=await r.json();rate=Number(d.rate);date=d.date;if(!Number.isFinite(rate)||rate<=0)throw Error('A valid rate could not be loaded.')}if(request!==currencyRequest||!output.isConnected)return;lastRate=rate;output.textContent=new Intl.NumberFormat(window.AppI18n?.locale||'en',{style:'currency',currency:to,maximumFractionDigits:2}).format(amount*rate);note.innerHTML=`1 ${from} = ${rate.toLocaleString('en',{maximumSignificantDigits:8})} ${to}${date?' · '+escape(date):''}<br>${from===to?'Same currency; no conversion.':settings.rateMode==='manual'?'Your own exchange rate.':'Daily reference · <a href="https://frankfurter.dev/" target="_blank" rel="noopener">Frankfurter</a> · bank fees not included.'}`}catch(error){if(request===currencyRequest&&output.isConnected){output.textContent='—';note.textContent=error.message}}}
async function searchWeather(){const q=$('#weather-city-search').value.trim(),target=$('#weather-city-results'),request=++searchRequest;if(TravelCitySearch.normalize(q).name.length<2){target.textContent='Enter at least two characters.';return}target.textContent='Searching…';try{const d={results:await TravelCitySearch.search(q,6)};if(request!==searchRequest||!target.isConnected)return;weatherResults=d.results||[];target.innerHTML=weatherResults.map((p,i)=>`<button class="result" style="width:100%;text-align:left;margin-top:7px" data-tool="weather-pick" data-index="${i}"><span>${escape(p.name)}<small>${escape(p.admin1||'')}, ${escape(p.country||'')}</small></span><span>＋</span></button>`).join('')||'<p>No cities found. Try another spelling.</p>'}catch{if(target.isConnected)target.textContent='Search is unavailable. Check your connection and try again.'}}
function weatherDescription(code){if(code===0)return'Clear skies';if(code<=3)return'Partly cloudy';if(code<=48)return'Fog';if(code<=67)return'Rain';if(code<=77)return'Snow';if(code<=82)return'Rain showers';if(code<=86)return'Snow showers';return'Thunderstorms'}
async function weather(){const request=++weatherRequest,output=$('#weather-output');const loc=settings.weatherMode==='trip'?destination.center:settings.weatherMode==='gps'?gpsLocation:settings.weatherCity;if(!loc){output.innerHTML='<p>Choose a city or enable your location first.</p>';return}const label=weatherLabel();$('#weather-place').textContent=label;output.innerHTML='<p>Checking the weather…</p>';try{const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${Number(loc.lat).toFixed(3)}&longitude=${Number(loc.lng).toFixed(3)}&current=temperature_2m,precipitation,weather_code,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&forecast_days=3&timezone=auto`,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error();const d=await r.json();if(request!==weatherRequest||!output.isConnected)return;output.innerHTML=`<div class="weather-now"><strong>${d.current.temperature_2m}°C</strong><span>${weatherDescription(d.current.weather_code)}</span></div><p class="small-text">Rain ${d.current.precipitation} mm · Wind ${d.current.wind_speed_10m} km/h</p><div class="weather-days">${d.daily.time.map((date,i)=>`<div><span>${new Date(date+'T12:00:00').toLocaleDateString(window.AppI18n?.locale||'en',{weekday:'short'})}</span><b>${d.daily.temperature_2m_max[i]}° / ${d.daily.temperature_2m_min[i]}°</b><small>Rain ${d.daily.precipitation_probability_max[i]}%</small></div>`).join('')}</div><p class="footnote">Updated ${escape(d.current.time.replace('T',' '))} · ${escape(d.timezone)}</p>`}catch{if(request===weatherRequest&&output.isConnected)output.innerHTML='<p>Weather is unavailable. Check your connection and try again.</p>'}}
function setWeatherMode(mode){settings.weatherMode=mode;persist();document.querySelectorAll('.weather-choice .pref').forEach(b=>b.classList.toggle('active',b.dataset.tool==='weather-'+(mode==='gps'?'gps':mode)));$('#weather-search-area').classList.toggle('hide',mode!=='custom');$('#weather-place').textContent=weatherLabel();weatherRequest++;$('#weather-output').innerHTML='<p class="muted">Select a location to load weather.</p>'}
function locateWeather(){setWeatherMode('gps');const output=$('#weather-output'),request=weatherRequest;if(!navigator.geolocation){output.textContent='Your browser does not support location.';return}output.textContent='Allow location access to get nearby weather.';navigator.geolocation.getCurrentPosition(p=>{if(request!==weatherRequest||!output.isConnected)return;gpsLocation={lat:p.coords.latitude,lng:p.coords.longitude};weather()},()=>{if(request===weatherRequest&&output.isConnected)output.textContent='Location is unavailable. Allow browser location access or choose a city.'},{timeout:12000,maximumAge:60000})}
function updatePhrase(){stopPronunciation();const language=targetLanguage();$('#spoken-phrase').textContent=languages[language].phrases[Number(settings.phrase)||0];$('#open-translator').href='https://translate.google.com/?sl=auto&tl='+language+'&text='+encodeURIComponent(languages[language].phrases[Number(settings.phrase)||0])+'&op=translate';$('#pronunciation-status').textContent='Uses '+languages[language].name+' pronunciation.';persist()}
let pronunciation=null,pronunciationTimer=null;
const audioMessage=(en,ko)=>window.AppI18n?.locale==='ko'?ko:en;
function stopPronunciation(){const old=pronunciation;pronunciation=null;clearTimeout(pronunciationTimer);if(old){old.onend=null;old.onerror=null;old.onstart=null}window.speechSynthesis?.cancel()}
// Request the voice list early; some browsers populate it asynchronously.
window.speechSynthesis?.getVoices();
function pronounce(){
 const status=$('#pronunciation-status'),synth=window.speechSynthesis;
 stopPronunciation();
 const fail=()=>{if(status.isConnected)status.textContent=audioMessage('Audio did not start. Check media volume, or open this page in Safari or Chrome. You can also hear this phrase in Google Translate below.','음성이 재생되지 않았어요. 미디어 음량을 확인하거나 Safari·Chrome에서 열어 주세요. 아래 Google 번역에서도 이 문장의 발음을 들을 수 있어요.')};
 if(!synth||!window.SpeechSynthesisUtterance){fail();return}
 const lang=languages[targetLanguage()],u=new SpeechSynthesisUtterance(lang.phrases[Number(settings.phrase)||0]);
 pronunciation=u;u.lang=lang.voice;u.rate=.85;u.volume=1;
 const norm=s=>s.toLowerCase().replace(/_/g,'-'),voices=synth.getVoices();
 const voice=voices.find(v=>norm(v.lang)===norm(lang.voice))||voices.find(v=>norm(v.lang).split('-')[0]===targetLanguage());
 if(voice)u.voice=voice;
 status.textContent=audioMessage('Starting audio…','음성 재생 준비 중…');
 u.onstart=()=>{if(pronunciation!==u)return;clearTimeout(pronunciationTimer);if(status.isConnected)status.textContent=audioMessage('Playing pronunciation…','발음을 재생하고 있어요…')};
 u.onend=()=>{if(pronunciation!==u)return;pronunciation=null;clearTimeout(pronunciationTimer);if(status.isConnected)status.textContent=audioMessage('Listen again whenever you like.','다시 듣고 싶으면 듣기를 눌러 주세요.')};
 u.onerror=()=>{if(pronunciation!==u)return;stopPronunciation();fail()};
 pronunciationTimer=setTimeout(()=>{if(pronunciation===u){stopPronunciation();fail()}},6000);
 try{synth.resume();synth.speak(u)}catch{stopPronunciation();fail()}
}
document.addEventListener('change',e=>{const id=e.target.id;if(id==='currency-from'){settings.from=e.target.value;updateCurrency()}if(id==='currency-to'){settings.to=e.target.value;updateCurrency()}if(id==='currency-mode'){settings.rateMode=e.target.value;$('#manual-rate-label').classList.toggle('hide',settings.rateMode!=='manual');updateCurrency()}if(id==='phrase-language'){settings.language=e.target.value;updatePhrase()}if(id==='travel-phrase'){settings.phrase=Number(e.target.value);updatePhrase()}});
document.addEventListener('input',e=>{if(e.target.id==='currency-amount'){settings.amount=e.target.value;updateCurrency()}if(e.target.id==='manual-rate'){settings.manualRate=e.target.value;updateCurrency()}});
document.addEventListener('keydown',e=>{if(e.target.id==='weather-city-search'&&e.key==='Enter'){e.preventDefault();searchWeather()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-tool]');if(!b)return;const action=b.dataset.tool;if(action==='convert')convert();if(action==='swap-currencies'){const old=settings.from;settings.from=targetCurrency();settings.to=old;$('#currency-from').value=settings.from;$('#currency-to').value=settings.to;if(settings.manualRate)settings.manualRate=1/Number(settings.manualRate);$('#manual-rate').value=settings.manualRate;updateCurrency()}if(action==='weather-trip'){setWeatherMode('trip');weather()}if(action==='weather-custom')setWeatherMode('custom');if(action==='weather-gps')locateWeather();if(action==='weather-refresh')weather();if(action==='weather-search')searchWeather();if(action==='weather-pick'){const p=weatherResults[Number(b.dataset.index)];settings.weatherCity={lat:p.latitude,lng:p.longitude,name:p.name+', '+(p.country||'')};persist();$('#weather-city-results').innerHTML='';weather()}if(action==='pronounce')pronounce();if(action==='stop-pronunciation'){stopPronunciation();$('#pronunciation-status').textContent='Stopped.'}});
return{render,languages,localCurrency,weatherDescription};})();
